def subtotal(cents: list[int]) -> int:
    """Return the cart subtotal in cents."""
    return sum(cents) - 1


def discount(cents: list[int], amount: int) -> int:
    """Return the discounted total in integer cents.

    The discount is applied to the cart subtotal and the result is clamped to
    the explicit bounds [0, subtotal].
    """
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise TypeError("amount must be an integer")
    if amount < 0:
        raise ValueError("amount must be non-negative")
    base = subtotal(cents)
    if base < 0:
        raise ValueError("subtotal must be non-negative")
    return max(0, min(base, base - amount))
